svg.script:
(() => {
  const ids = ['zig1','zig2','zig3','archesUp','archesDown','loops1','loops2','spikes1','spikes2','eloops1','eloops2','wave1','wave2'];
  const pencil = document.getElementById('pencil');
  const glow = document.getElementById('startGlow');
  const sleep = ms => new Promise(r => setTimeout(r,ms));

  function pose(path,len,d) {
    const p = path.getPointAtLength(d);
    const q = path.getPointAtLength(Math.min(len,d+1.2));
    const a = Math.atan2(q.y-p.y,q.x-p.x)*180/Math.PI;
    return {x:p.x,y:p.y,a};
  }

  async function trace(id) {
    const path = document.getElementById(id);
    const line = document.getElementById('draw-'+id);
    const len = path.getTotalLength();
    const s = pose(path,len,0);

    pencil.style.transition='transform 300ms ease-in-out';
    pencil.setAttribute('transform',`translate(${s.x} ${s.y}) rotate(${s.a})`);

    glow.setAttribute('cx',s.x);
    glow.setAttribute('cy',s.y);
    glow.style.opacity='.7';
    await sleep(330);
    glow.style.opacity='0';

    line.style.opacity='.98';
    line.style.strokeDashoffset='1';
    pencil.style.transition='none';

    const begin=performance.now();
    const duration=Math.max(650,Math.min(2300,len*4.2));

    await new Promise(done=>{
      function frame(now) {
        const raw=Math.min(1,(now-begin)/duration);
        const t=raw<.5 ? 2*raw*raw : 1-Math.pow(-2*raw+2,2)/2;
        const p=pose(path,len,len*t);

        pencil.setAttribute('transform',
          `translate(${p.x} ${p.y}) rotate(${p.a})`);
        line.style.strokeDashoffset=String(1-t);

        if(raw<1) requestAnimationFrame(frame);
        else done();
      }
      requestAnimationFrame(frame);
    });

    await sleep(180);
  }

  async function loop() {
    while(true) {
      ids.forEach(id=>{
        const line=document.getElementById('draw-'+id);
        line.style.opacity='0';
        line.style.strokeDashoffset='1';
      });
      await sleep(500);

      for(const id of ids) await trace(id);

      await sleep(1400);
    }
  }

  setTimeout(loop,700);
})();
